[DataContract]
class TFMUnitOfMeasureContextContract
{
    str         listOfUnitOfMeasure;
    UnitIDBase  unitId;

}

Method.Source:
[DataMemberAttribute('ListOfUnitsOfMeasure')]
public str parmListOfUnitOfMeasure(str _listOfUnitOfMeasure = listOfUnitOfMeasure)
{
    listOfUnitOfMeasure = _listOfUnitOfMeasure;
    return listOfUnitOfMeasure;
}

[DataMemberAttribute('DefaultUnitID')]
public str parmDefaultUnitId(str _unitId = unitId)
{
    unitId = _unitId;
    return unitId;
}
